    return {'final_balance': balance, 'history': history}

def simulate_investment_fund(initial_balance: float, monthly_contribution: float, annual_return: float, years: int) -> dict:
    # Validate inputs
    if not isinstance(initial_balance, (int, float)) or initial_balance < 0:
        raise ValueError("Initial balance must be a non-negative number.")
    if not isinstance(monthly_contribution, (int, float)) or monthly_contribution < 0:
        raise ValueError("Monthly contribution must be a non-negative number.")
    if not isinstance(annual_return, (int, float)):
        raise ValueError("Annual return must be a number.")
    if not isinstance(years, int) or years < 0:
        raise ValueError("Years must be a non-negative integer.")

    # Handle edge case where years is zero
    if years == 0:
        return {'final_balance': initial_balance, 'history': [initial_balance]}

    # Calculate monthly return rate
    monthly_return = (1 + annual_return) ** (1 / 12) - 1

    # Initialize balance and history
    balance = initial_balance
    history = [balance]

    # Simulate monthly contributions and returns
    for _ in range(years * 12):
        balance *= (1 + monthly_return)  # Apply monthly return
        balance += monthly_contribution  # Add monthly contribution
        history.append(balance)

    # Handle potential floating-point precision issues
    final_balance = round(balance, 2)  # Round to 2 decimal places for realistic currency representation

    return {'final_balance': final_balance, 'history': history}
